-- ------------------------------------------------------------
-- 3. BASE
-- ------------------------------------------------------------
base AS (
  SELECT
    f.ad_format,
    cs.creative_id,
    cs.advertiser_id,
    cs.advertiser_disclosed_name        AS advertiser,
    cs.advertiser_location              AS loc,
    CASE
      WHEN rs.region_code IN (
        'AT','BE','BG','CY','CZ','DE','DK','EE','ES','FI',
        'FR','GR','HR','HU','IE','IT','LT','LU','LV','MT',
        'NL','PL','PT','RO','SE','SI','SK','IS','LI','NO'
      ) THEN 'EEA'
      ELSE rs.region_code
    END                                 AS region_code,
    DATE(rs.first_shown)                AS first_seen,
    DATE(rs.last_shown)                 AS last_seen,
    CASE
      WHEN SAFE_CAST(rs.times_shown_upper_bound AS FLOAT64) >= 1e9 THEN NULL
      WHEN rs.times_shown_lower_bound IS NOT NULL AND rs.times_shown_upper_bound IS NOT NULL
        THEN (
          SAFE_CAST(rs.times_shown_lower_bound AS FLOAT64) +
          SAFE_CAST(rs.times_shown_upper_bound AS FLOAT64)
        ) / 2
      ELSE NULL
    END AS impressions_midpoint_clean
  FROM format_ids f
  JOIN `bigquery-public-data.google_ads_transparency_center.creative_stats` cs
    ON cs.creative_id = f.creative_id
  CROSS JOIN UNNEST(cs.region_stats) rs
  WHERE rs.first_shown IS NOT NULL
    AND rs.region_code != 'EEA'
),

-- ------------------------------------------------------------
-- 4. AD-LEVEL AGGREGATION
-- ------------------------------------------------------------
ad_level AS (
  SELECT
    ad_format,
    creative_id,
    ANY_VALUE(advertiser_id)            AS advertiser_id,
    ANY_VALUE(advertiser)               AS advertiser,
    ANY_VALUE(loc)                      AS loc,
    MIN(first_seen)                     AS first_seen,
    MAX(last_seen)                      AS last_seen,
    COUNT(DISTINCT region_code)         AS region_count,
    SUM(impressions_midpoint_clean)     AS viol_impressions
  FROM base
  GROUP BY ad_format, creative_id
),

-- ------------------------------------------------------------
-- 5. ADVERTISER-LEVEL AGGREGATION
-- ------------------------------------------------------------
advertiser_level AS (
  SELECT
    ad_format,
    advertiser_id,
    ANY_VALUE(advertiser)               AS advertiser,
    ANY_VALUE(loc)                      AS loc,
    COUNT(DISTINCT creative_id)         AS viol_ads,
    SUM(viol_impressions)               AS viol_impressions,
    MAX(region_count)                   AS max_regions,
    DATE_DIFF(MAX(last_seen), MIN(first_seen), DAY) AS days_active
  FROM ad_level
  GROUP BY ad_format, advertiser_id
),

-- ------------------------------------------------------------
-- 6. TOTAL IMPRESSIONS PER ADVERTISER (all their ads)
-- ------------------------------------------------------------
advertiser_total AS (
  SELECT
    cs.advertiser_id,
    SUM(
      CASE
        WHEN SAFE_CAST(rs.times_shown_upper_bound AS FLOAT64) >= 1e9 THEN NULL
        WHEN rs.times_shown_lower_bound IS NOT NULL AND rs.times_shown_upper_bound IS NOT NULL
          THEN (
            SAFE_CAST(rs.times_shown_lower_bound AS FLOAT64) +
            SAFE_CAST(rs.times_shown_upper_bound AS FLOAT64)
          ) / 2
        ELSE NULL
      END
    ) AS total_impressions
  FROM `bigquery-public-data.google_ads_transparency_center.creative_stats` cs
  CROSS JOIN UNNEST(cs.region_stats) rs
  WHERE rs.region_code != 'EEA'
  GROUP BY cs.advertiser_id
)

-- ------------------------------------------------------------
-- 7. FINAL: TOP 5 PER AD FORMAT SORTED BY VIOL IMPRESSIONS
-- ------------------------------------------------------------
SELECT
  ad_format,
  advertiser,
  loc,
  viol_ads,
  viol_impressions_fmt    AS viol_impressions,
  total_impressions_fmt   AS total_impressions,
  regions,
  days
FROM (
  SELECT
    al.ad_format,
    al.advertiser,
    al.loc,
    al.viol_ads,
    al.max_regions                      AS regions,
    al.days_active                      AS days,
    CASE
      WHEN al.viol_impressions >= 1000000000
        THEN CONCAT(FORMAT('%.2f', al.viol_impressions / 1000000000), 'B')
      WHEN al.viol_impressions >= 1000000
        THEN CONCAT(FORMAT('%.2f', al.viol_impressions / 1000000), 'M')
      WHEN al.viol_impressions >= 1000
        THEN CONCAT(FORMAT('%.2f', al.viol_impressions / 1000), 'K')
      ELSE FORMAT('%0.0f', al.viol_impressions)
    END                                 AS viol_impressions_fmt,
    CASE
      WHEN adv_total.total_impressions >= 1000000000
        THEN CONCAT(FORMAT('%.2f', adv_total.total_impressions / 1000000000), 'B')
      WHEN adv_total.total_impressions >= 1000000
        THEN CONCAT(FORMAT('%.2f', adv_total.total_impressions / 1000000), 'M')
      WHEN adv_total.total_impressions >= 1000
        THEN CONCAT(FORMAT('%.2f', adv_total.total_impressions / 1000), 'K')
      ELSE FORMAT('%0.0f', adv_total.total_impressions)
    END                                 AS total_impressions_fmt,
    ROW_NUMBER() OVER (
      PARTITION BY al.ad_format
      ORDER BY al.viol_impressions DESC NULLS LAST
    ) AS rn
  FROM advertiser_level al
  LEFT JOIN advertiser_total adv_total
    ON adv_total.advertiser_id = al.advertiser_id
)
WHERE rn <= 5
ORDER BY ad_format, viol_ads DESC;
